"enem-2019-99":{"fingerprint":"a10abaaa","subject":"biologia","topic":"Decomposição e ciclos de carbono e nitrogênio","answerExpected":"A","paragraphs":["Os açúcares e a pectina trazem carbono orgânico, enquanto os alcaloides contêm nitrogênio.","Na decomposição do resíduo, microrganismos transformam essas substâncias e devolvem seus elementos aos ciclos do solo e do ambiente."],"sourcePage":4,"corrections":{"alternatives":[{"letter":"A","text":"Possibilita a reciclagem de carbono e nitrogênio.","file":null},{"letter":"B","text":"Promove o deslocamento do alumínio, que é tóxico.","file":null},{"letter":"C","text":"Melhora a compactação do solo por causa da presença de pectina.","file":null},{"letter":"D","text":"eleva o pH do solo em função da degradação dos componentes do resíduo.","file":null},{"letter":"E","text":"Apresenta efeitos inibidores de crescimento para a maioria das espécies vegetais pela cafeína.","file":null}]}},
